#include <iostream>

int estimar(int piezas) {
    if (piezas < 0 || piezas > 10) {
        return -1;
    }

    if (piezas == 0) {
        return 0;
    }

    return 3 + 2 * piezas;
}

bool verificar(int piezas, int esperado) {
    int real{estimar(piezas)};
    bool coincide{real == esperado};

    std::cout << "Piezas=" << piezas << " real=" << real
              << " esperado=" << esperado << " ";

    if (coincide) {
        std::cout << "Correcto\n";
    } else {
        std::cout << "Fallo\n";
    }

    return coincide;
}

int main() {
    int fallos{0};

    if (!verificar(-1, -1)) {
        ++fallos;
    }
    if (!verificar(0, 0)) {
        ++fallos;
    }
    if (!verificar(1, 5)) {
        ++fallos;
    }
    if (!verificar(4, 11)) {
        ++fallos;
    }
    if (!verificar(10, 23)) {
        ++fallos;
    }
    if (!verificar(11, -1)) {
        ++fallos;
    }

    std::cout << "Fallos=" << fallos;

    return 0;
}

